import{_ as i,o as t,c as e,a2 as s}from"./chunks/framework.apcphSFn.js";const k=JSON.parse('{"title":"选择接入方式","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":1786056696000}'),p={name:"getting-started/index.md"};function d(n,a,h,l,o,r){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="选择接入方式" tabindex="-1">选择接入方式 <a class="header-anchor" href="#选择接入方式" aria-label="Permalink to &quot;选择接入方式&quot;">​</a></h1><p>xapiforge 的代码生成方式在各运行环境中相同。真正不同的是 Token 存储、网络实现和文件下载能力。先按应用运行位置选择指南，不需要把三个 adapter 都装上。</p><table tabindex="0"><thead><tr><th>运行环境</th><th>使用的 adapter</th><th>从这里开始</th></tr></thead><tbody><tr><td>Vue、React、普通 Web 应用</td><td><code>@xapiforge/adapter-browser</code></td><td><a href="./browser">浏览器应用接入</a></td></tr><tr><td>Ionic / Capacitor</td><td><code>@xapiforge/adapter-capacitor</code></td><td><a href="./ionic-capacitor">Ionic / Capacitor 接入</a></td></tr><tr><td>React Native</td><td><code>@xapiforge/adapter-react-native</code></td><td><a href="./react-native">React Native 接入</a></td></tr></tbody></table><h2 id="所有项目都要完成的四件事" tabindex="-1">所有项目都要完成的四件事 <a class="header-anchor" href="#所有项目都要完成的四件事" aria-label="Permalink to &quot;所有项目都要完成的四件事&quot;">​</a></h2><ol><li>安装 <code>@xapiforge/core</code>、<code>@xapiforge/genapi</code> 和一个运行时 adapter。</li><li>创建 <code>xapiforge.config.ts</code>，配置 OpenAPI 地址和生成目录。</li><li>执行 <code>xapiforge-fetch</code> 和 <code>xapiforge</code>，得到强类型客户端。</li><li>创建 <code>AuthService</code>，把它和对应的 TokenStore 传给生成客户端。</li></ol><p>生成客户端以后，业务代码只使用生成结果，例如：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.base.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/health&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>路径、参数和返回值来自项目自己的 OpenAPI 文档。文档中的 <code>/api/health</code>、端口和 OAuth 字段只是示例，接入时要替换成真实后端协议。</p><h2 id="只是想先看效果" tabindex="-1">只是想先看效果 <a class="header-anchor" href="#只是想先看效果" aria-label="Permalink to &quot;只是想先看效果&quot;">​</a></h2><p>仓库中的 <code>examples/demo-app</code> 可以直接连接本地 mock-server：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mock</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@xapiforge/example-demo-app&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <code>http://localhost:5173</code>。这个 demo 用于理解调用方式和运行回归场景，不应原样复制成业务项目。</p><h2 id="生成文件是否提交到-git" tabindex="-1">生成文件是否提交到 Git <a class="header-anchor" href="#生成文件是否提交到-git" aria-label="Permalink to &quot;生成文件是否提交到 Git&quot;">​</a></h2><p>两种方式都可以，但团队只能选一种：</p><ul><li>提交生成文件：代码审查能看到 API 变化，仓库会出现较大的生成 diff。</li><li>构建时生成：仓库更干净，但 CI 必须能拿到固定版本的 OpenAPI 文档。</li></ul><p>如果后端文档会随环境变化，建议把审核过的 swagger.json 和生成结果一起提交，避免同一个前端提交在不同时间生成不同代码。</p>`,16)])])}const g=i(p,[["render",d]]);export{k as __pageData,g as default};
